  float high_x=s->config.calibrated ? s->config.max_x : s->config.limit;
  float low_y=s->config.calibrated ? s->config.min_y : fmaxf(-s->config.limit,-120);
  float high_y=s->config.calibrated ? s->config.max_y : s->config.limit;
