  ["docs", "python -c \"from pathlib import Path; fs=['docs/持久启动准备_20261012.md','docs/决赛开机自启动接续_20261010.md','docs/代码日志对应表.md','docs/整机稳定性验收_20260917.md'];\nfor n in fs:\n p=Path(n); print('\\\\n### '+n); lines=p.read_text(encoding='utf-8',errors='replace').splitlines();\n for i,l in enumerate(lines):\n  if any(k in l for k in ['最新','阻塞','当前状态','下一步','验收','跟随','自然','串口','接续','2026-10-13']):\n   print(f'{i+1}: {l[:500]}')\""],
