];
const out = await Promise.all(jobs.map(async ([name, cmd]) => {
  const r = await tools.exec_command({cmd, workdir:"E:\\openvela\\VelaVision",yield_time_ms:10000,max_output_tokens:name==="tracker"?8500:5000});
  return `=== ${name} ===\n${r.output}`;
}));
out.forEach(text);

