#ifndef K7_TRACK_H
#define K7_TRACK_H
#include <stdbool.h>
#include <stdint.h>
#include "k7_yunet.h"
enum k7_track_axes_e { TRACK_X = 1, TRACK_Y = 2, TRACK_XY = 3 };
struct k7_track_config_s {
  bool transmit; int limit, sign_x, sign_y; unsigned int axes; bool preview;
  bool calibrated; bool photo;
  bool voice_control; /* Keep one capture session; start with motion held. */
  int min_x, max_x, min_y, max_y, center_x, center_y;
};
enum k7_track_state_e { TRACK_LOST, TRACK_CONFIRM, TRACK_ACTIVE, TRACK_STALE, TRACK_HALTED, TRACK_CLIPPED, TRACK_STATE_COUNT };
struct k7_track_s
{
  struct k7_track_config_s config;
  struct k7_face_s previous;
  bool have_previous;
  unsigned int hits_x, hits_y;
  unsigned int edge_y, edge_y_hits;
  unsigned int edge_x, edge_x_hits;
  float filtered_x, filtered_y, target_x, target_y;
  uint64_t previous_time, previous_sample;
  int sent_x, sent_y;
};
struct k7_track_result_s
{
  enum k7_track_state_e state;
  bool update;
  int x, y;
  float dx, dy;
  bool has_face;
  struct k7_face_s box;
  unsigned int edges; /* left=1, top=2, right=4, bottom=8 */
};
int k7_track_init(struct k7_track_s *, const struct k7_track_config_s *,
                  int initial_x, int initial_y);
void k7_track_step(struct k7_track_s *, const struct k7_faces_s *,
                    uint64_t now, uint64_t sample, bool halted,
                    struct k7_track_result_s *);
#endif
/* Offline controller regression; does not model servo mechanics. */
#include "k7_track.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
static struct k7_track_config_s cfg={.axes=TRACK_XY,.sign_x=1,.sign_y=1,
 .calibrated=true,.min_x=-800,.max_x=800,.min_y=-120,.max_y=1030};
static struct k7_faces_s face(float x,float y)
{struct k7_faces_s f={.count=1};f.face[0]=(struct k7_face_s){x,y,30,30,.95f};return f;}
int main(void)
{
 struct k7_track_s s;struct k7_track_result_s r;
 struct k7_faces_s f=face(89,57);unsigned long long now=1000000;
 assert(k7_track_init(&s,&cfg,0,0)==0);
 for(int i=0;i<11;i++){now+=100000;k7_track_step(&s,&f,now,now-10000,0,&r);}
 int response_x=r.x,response_y=r.y;assert(response_x>0&&response_y>0);
 int x=r.x,y=r.y;
 k7_track_step(&s,&f,now+100000,now-400000,0,&r);assert(r.state==TRACK_STALE&&r.x==x&&r.y==y&&!r.update);
 k7_track_step(&s,&f,now+200000,now+200001,0,&r);assert(r.state==TRACK_STALE&&!r.update);
 k7_track_step(&s,&f,now+300000,now+290000,1,&r);assert(r.state==TRACK_HALTED&&!r.update);
 struct k7_faces_s none={0};k7_track_step(&s,&none,now+400000,now+390000,0,&r);assert(r.state==TRACK_LOST&&!r.update);
 assert(k7_track_init(&s,&cfg,0,0)==0);f=face(65,45);
 for(int i=0;i<100;i++){now+=33333;k7_track_step(&s,&f,now,now-10000,0,&r);assert(r.x==0&&r.y==0&&!r.update);}
 f=face(125,70);int previous=0;
 for(int i=0;i<500;i++){unsigned dt=(i%2)?50000:100000;now+=dt;k7_track_step(&s,&f,now,now-10000,0,&r);
  assert(abs(r.x-previous)<=(int)ceilf(fminf(37.5f,375.0f*dt/1000000.f)));
  assert(r.x>=-800&&r.x<=800&&r.y>=-120&&r.y<=1030);previous=r.x;}
 /* Center crossing must not drive in the old direction. */
 previous=r.x;f=face(10,45);now+=100000;k7_track_step(&s,&f,now,now-10000,0,&r);assert(r.x<=previous);
 /* Clipped Y recovery retains its slower 60-units/s cap. */
 assert(k7_track_init(&s,&cfg,0,0)==0);f=face(65,90);previous=0;
 for(int i=0;i<20;i++){now+=100000;k7_track_step(&s,&f,now,now-10000,0,&r);assert(abs(r.y-previous)<=6);previous=r.y;}
 printf("response_x=%d response_y=%d protections=PASS\n",response_x,response_y);
 return 0;
}
/* Regression: a visible side-clipped face must recover without blind motion. */
#include "k7_track.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
static struct k7_track_config_s cfg={.axes=TRACK_XY,.sign_x=1,.sign_y=1,
 .calibrated=true,.min_x=-800,.max_x=800,.min_y=-120,.max_y=1030};
static struct k7_faces_s face(float x,float width)
{struct k7_faces_s f={.count=1};f.face[0]=(struct k7_face_s){x,30,width,60,.95f};return f;}
static void step(struct k7_track_s *s,struct k7_faces_s *f,unsigned long long *t,struct k7_track_result_s *r)
{*t+=80000;k7_track_step(s,f,*t,*t-10000,0,r);}
int main(void)
{
 struct k7_track_s s;struct k7_track_result_s r;unsigned long long t=1000000;
 for(int sign=-1;sign<=1;sign+=2)for(int side=0;side<2;side++){
  cfg.sign_x=sign;assert(!k7_track_init(&s,&cfg,0,0));
  struct k7_faces_s f=side?face(105,55):face(0,55);
  step(&s,&f,&t,&r);assert(!r.update);
  step(&s,&f,&t,&r);assert(r.update && r.x*sign*(side?1:-1)>0 && abs(r.x)<=12);
  int prev=r.x;
  for(int i=0;i<100;i++){
   /* Alternate exact clipping and subpixel near-edge boxes. */
   f=side?face(105,(i%2)?54.6f:55.f):face((i%2)?.4f:0,55);
   step(&s,&f,&t,&r);assert(abs(r.x-prev)<=12);assert(r.x>=-800&&r.x<=800);prev=r.x;
  }
  struct k7_faces_s none={0};step(&s,&none,&t,&r);assert(!r.update&&r.x==prev&&r.state==TRACK_LOST);
  step(&s,&f,&t,&r);assert(!r.update); /* Reconfirm after losing face. */
  step(&s,&f,&t,&r);
  prev=r.x;t+=80000;k7_track_step(&s,&f,t,t-300000,0,&r);assert(!r.update&&r.x==prev&&r.state==TRACK_STALE);
  step(&s,&f,&t,&r);assert(!r.update);
  t+=80000;k7_track_step(&s,&f,t,t-10000,1,&r);assert(!r.update&&r.state==TRACK_HALTED);
 }
 cfg.sign_x=1;assert(!k7_track_init(&s,&cfg,0,0));
 struct k7_faces_s both=face(0,160);
 for(int i=0;i<10;i++){step(&s,&both,&t,&r);assert(!r.update&&r.x==0);}
 /* Edge direction changes require fresh confirmation. */
 struct k7_faces_s l=face(0,55),rr=face(105,55);
 step(&s,&l,&t,&r);step(&s,&l,&t,&r);int prev=r.x;
 step(&s,&rr,&t,&r);assert(r.x==prev);step(&s,&rr,&t,&r);assert(r.x>prev);
 /* The disabled X axis must stay still even with a clipped face. */
 cfg.axes=TRACK_Y;assert(!k7_track_init(&s,&cfg,0,0));
 for(int i=0;i<10;i++){step(&s,&rr,&t,&r);assert(r.x==0);}
 puts("horizontal edge recovery and protections PASS");return 0;
}
/* Regression: a visible side-clipped face must recover without blind motion. */
#include "k7_track.h"
