static struct k7_faces_s face(float y,float height)
{struct k7_faces_s f={.count=1};f.face[0]=(struct k7_face_s){50,y,60,height,.95f};return f;}
static void step(struct k7_track_s *s,struct k7_faces_s *f,unsigned long long *t,struct k7_track_result_s *r)
{*t+=80000;k7_track_step(s,f,*t,*t-10000,0,r);}
int main(void)
{
 struct k7_track_s s;struct k7_track_result_s r;unsigned long long t=1000000;
 for(int sign=-1;sign<=1;sign+=2)for(int side=0;side<2;side++){
  cfg.sign_y=sign;assert(!k7_track_init(&s,&cfg,0,0));
  struct k7_faces_s f=side?face(80,40):face(0,40);
  step(&s,&f,&t,&r);assert(!r.update);
  step(&s,&f,&t,&r);assert(r.update && r.y*sign*(side?1:-1)>0 && abs(r.y)<=5);
  int prev=r.y;
  for(int i=0;i<100;i++){
   /* Alternate exact clipping and subpixel near-edge boxes. */
   f=side?face(80,(i%2)?39.6f:40.f):face((i%2)?.4f:0,40);
   step(&s,&f,&t,&r);assert(abs(r.y-prev)<=5);assert(r.y>=-120&&r.y<=1030);prev=r.y;
  }
  struct k7_faces_s none={0};step(&s,&none,&t,&r);assert(!r.update&&r.y==prev&&r.state==TRACK_LOST);
  step(&s,&f,&t,&r);assert(!r.update); /* Reconfirm after losing face. */
  step(&s,&f,&t,&r);
  prev=r.y;t+=80000;k7_track_step(&s,&f,t,t-300000,0,&r);assert(!r.update&&r.y==prev&&r.state==TRACK_STALE);
  step(&s,&f,&t,&r);assert(!r.update);
  t+=80000;k7_track_step(&s,&f,t,t-10000,1,&r);assert(!r.update&&r.state==TRACK_HALTED);
 }
 cfg.sign_y=1;assert(!k7_track_init(&s,&cfg,0,0));
 struct k7_faces_s both=face(0,120);
 for(int i=0;i<10;i++){step(&s,&both,&t,&r);assert(!r.update&&r.y==0);}
 /* Edge direction changes require fresh confirmation. */
 struct k7_faces_s l=face(0,40),rr=face(80,40);
 step(&s,&l,&t,&r);step(&s,&l,&t,&r);int prev=r.y;
 step(&s,&rr,&t,&r);assert(r.y==prev);step(&s,&rr,&t,&r);assert(r.y>prev);
 /* The disabled Y axis must stay still even with a clipped face. */
 cfg.axes=TRACK_X;assert(!k7_track_init(&s,&cfg,0,0));
 for(int i=0;i<10;i++){step(&s,&rr,&t,&r);assert(r.y==0);}
 puts("vertical edge recovery and protections PASS");return 0;
}

