  [string]$OutputRoot = ''
)
$ErrorActionPreference = 'Stop'
if (-not $OutputRoot) { $OutputRoot = Join-Path $PSScriptRoot '../evidence/windows-device' }

function Get-K7Assessment($Devices, $Ports) {
  $nativeSerial = @($Devices | Where-Object { $_.InstanceId -match '^USB\\VID_1A86&PID_7523(?:\\|&)' })
  $fastboot = @($Devices | Where-Object { $_.InstanceId -match '^USB\\VID_18D1&PID_4D00' })
  $rockusb = @($Devices | Where-Object { $_.InstanceId -match '^USB\\VID_2207&PID_350E' })
  $proxies = @($Devices | Where-Object { $_.InstanceId -match '^USB\\VID_0E0F&PID_0001' })
  $nativePorts = @($Ports | Where-Object { $_.PNPDeviceID -match '^USB\\VID_1A86&PID_7523(?:\\|&)' -and $_.DeviceID -match '^COM[0-9]+$' })
  $matchedPorts = @($nativePorts | Where-Object { $nativeSerial.InstanceId -contains $_.PNPDeviceID })
  $serialState = 'not_available_in_windows'
  if ($nativePorts.Count -gt 1 -or $nativeSerial.Count -gt 1) { $serialState = 'ambiguous' }
  elseif ($nativeSerial.Count -eq 1) {
    $device = $nativeSerial[0]
    if ($device.Status -ne 'OK' -or ($null -ne $device.ProblemCode -and $device.ProblemCode -ne 0)) { $serialState = 'native_driver_error' }
    elseif ($nativePorts.Count -eq 0) { $serialState = 'port_not_exposed' }
    elseif ($matchedPorts.Count -ne 1) { $serialState = 'inventory_mismatch' }
    else { $serialState = 'enumerated_not_opened' }
  }
  elseif ($nativePorts.Count -ne 0) { $serialState = 'inventory_mismatch' }
  $otgState = 'not_enumerated_in_windows'
  if (($fastboot.Count + $rockusb.Count) -gt 1) { $otgState = 'ambiguous' }
  elseif (($fastboot.Count + $rockusb.Count) -eq 1) {
    $device = @($fastboot + $rockusb)[0]
    if ($device.Status -ne 'OK' -or ($null -ne $device.ProblemCode -and $device.ProblemCode -ne 0)) { $otgState = 'native_driver_error' }
    elseif ($fastboot.Count -eq 1) { $otgState = 'fastboot_enumerated_transfer_untested' }
    else { $otgState = 'rockusb_enumerated_transfer_untested' }
  }
  [pscustomobject]@{
    serial_state = $serialState
    serial_ports = @($matchedPorts | ForEach-Object { $_.DeviceID })
    serial_candidate_ports = @($nativePorts | ForEach-Object { $_.DeviceID })
    otg_state = $otgState
    vmware_proxy_count = $proxies.Count
    vmware_proxy_error_count = @($proxies | Where-Object { $_.Status -ne 'OK' }).Count
    # A proxy cannot be identified as this board from VID/PID alone.
    proxy_identity_verified = $false
    firmware_ready = $false
    transfer_verified = $false
  }
}

function Resolve-K7SerialPorts($Devices, $CimPorts, $RegistryPorts, $SystemPortNames, $SerialCommNames) {
  $ports = @($CimPorts | ForEach-Object {
    [pscustomobject]@{ DeviceID=$_.DeviceID; Name=$_.Name; PNPDeviceID=$_.PNPDeviceID; Source='Win32_SerialPort' }
  })
  $result = [pscustomobject]@{ ports=$ports; fallback_state='not_used' }
  $native = @($Devices | Where-Object { $_.InstanceId -match '^USB\\VID_1A86&PID_7523(?:\\|&)' })
  # A registry fallback never supersedes an existing CH340 CIM mapping.
  if (@($ports | Where-Object { $_.PNPDeviceID -match '^USB\\VID_1A86&PID_7523(?:\\|&)' }).Count -ne 0) { return $result }
  if ($native.Count -ne 1) { $result.fallback_state='requires_unique_pnp'; return $result }
  $device = $native[0]
  if ($device.Status -ne 'OK' -or $null -eq $device.ProblemCode -or $device.ProblemCode -ne 0) {
    $result.fallback_state='requires_healthy_pnp'; return $result
  }
  $registry = @($RegistryPorts | Where-Object { $_.PNPDeviceID -eq $device.InstanceId })
  if ($registry.Count -ne 1 -or $registry[0].PortName -notmatch '^COM[0-9]+$') {
    $result.fallback_state='missing_instance_port_name'; return $result
  }
  $portName = $registry[0].PortName.ToUpperInvariant()
  if (@($ports | Where-Object { $_.DeviceID -eq $portName }).Count -ne 0) {
    $result.fallback_state='cim_port_conflict'; return $result
  }
  if (@($SystemPortNames | Where-Object { $_ -eq $portName }).Count -ne 1 -or
      @($SerialCommNames | Where-Object { $_ -eq $portName }).Count -ne 1) {
    $result.fallback_state='port_sources_disagree'; return $result
  }
  $result.ports = @($ports) + @([pscustomobject]@{
    DeviceID=$portName; Name=$device.FriendlyName; PNPDeviceID=$device.InstanceId
    Source='PnP-instance-PortName+SerialPort.GetPortNames+SERIALCOMM'
  })
  $result.fallback_state='verified'
  return $result
}

function Get-K7Inventory {
  $devices = @(Get-PnpDevice -PresentOnly | Where-Object {
    $_.InstanceId -match '^USB\\VID_(1A86&PID_7523|18D1&PID_4D00|2207&PID_350E|0E0F&PID_0001)'
  } | ForEach-Object {
    $problemCode = $null
    try { $problemCode = (Get-PnpDeviceProperty -InstanceId $_.InstanceId -KeyName DEVPKEY_Device_ProblemCode).Data } catch {}
    [pscustomobject]@{ Status = [string]$_.Status; FriendlyName = $_.FriendlyName; InstanceId = $_.InstanceId; ProblemCode = $problemCode }

