# Shared native COM3 control with durable raw logs and bounded Fastboot calls.
. (Join-Path $PSScriptRoot 'k7_device.ps1')
function Save-Native { $nativeReport | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath (Join-Path $nativeOut 'result.json') -Encoding UTF8 }
function Send-Native([string]$Command) {
  $nativeReport.commands+=@{command=$Command;at=[DateTime]::UtcNow.ToString('o');state='intended'};Save-Native
  foreach ($nativeByte in [Text.Encoding]::ASCII.GetBytes($Command+"`r")) {$nativeSerial.Write([byte[]]@($nativeByte),0,1);Start-Sleep -Milliseconds 4}
}
function Read-Native([string]$Pattern,[int]$Seconds=20) {
  $nativeText=New-Object Text.StringBuilder;$nativeTimer=[Diagnostics.Stopwatch]::StartNew();$nativeBuffer=New-Object byte[] 32768
  while ($nativeTimer.Elapsed.TotalSeconds -lt $Seconds) {
    try {$nativeN=$nativeSerial.Read($nativeBuffer,0,$nativeBuffer.Length)} catch [TimeoutException] {continue}
    if ($nativeN -gt 0) {
      $nativeLog.Write($nativeBuffer,0,$nativeN);$nativeLog.Flush()
      $null=$nativeText.Append([Text.Encoding]::ASCII.GetString($nativeBuffer,0,$nativeN))
      $nativeClean=$nativeText.ToString() -replace '\x1b\[[0-9;]*[A-Za-z]',''
      if ($nativeClean -match $Pattern) {return $nativeClean}
    }
  }
  throw ('Serial response timeout; no retry: '+$Pattern)
}
function Command-Native([string]$Command) {
  Send-Native $Command;$nativeReply=Read-Native '(?m)(?:^|\n)=>\s*$'
  # md.l's ASCII column may legitimately contain firmware help/error strings.
  if ($nativeReply -match '(?m)^\s*(?:Unknown command\b|Usage:)') {throw ('Command rejected: '+$Command)}
  return $nativeReply
}
function Exit-FastbootNative {
  $nativeSerial.Write([byte[]]@(3),0,1);$null=Read-Native '(?m)(?:^|\n)=>\s*$'
}
