"""Collect and verify the isolated smooth-tracking ARM64 build artifacts."""
import base64
import hashlib
import json
from pathlib import Path

from cloud_radio_stage_audit import ROOT, remote
from generate_embedded_radio import INPUTS

EV = 'evidence/tracking-smooth-20261013'
BUILD = 'cmake_out/velavision_tracking_smooth_20261013'


def main():
    out = ROOT / EV
    report_path = out / 'verification.json'
    if report_path.exists():
        raise RuntimeError('Verification already exists; inspect instead of replacing it')
    code = r"""
import base64,hashlib,json,pathlib,subprocess
sdk=pathlib.Path('/home/swl/openvela')
root=sdk/'work/velavision-project'
build=sdk/BUILD
ev=root/EV
assert (ev/'build.exit').read_text().strip()=='0'
sync=json.loads((ev/'sync.json').read_text())
assert [r['mode'] for r in sync]==['--check','--apply','--check']
assert all(r['exit_code']==0 for r in sync)
nm=sdk/'prebuilts/gcc/linux-x86_64/aarch64-none-elf/bin/aarch64-none-elf-nm'
lines=subprocess.check_output([str(nm),'-S',str(build/'nuttx')]).decode().splitlines()
raw=(build/'nuttx.bin').read_bytes()
arrays=[]
for name,symbol,size,digest in INPUTS:
 match=[s.split() for s in lines if s.split()[-1]=='g_k7radio_'+symbol]
 assert len(match)==1 and match[0][-2]=='R'
 addr=int(match[0][0],16)
 assert int(match[0][1],16)==size
 data=raw[addr-0x40400000:addr-0x40400000+size]
 assert hashlib.sha256(data).hexdigest()==digest, 'Linked array mismatch: '+name
 arrays.append({'name':name,'address':hex(addr),'bytes':size,'sha256':digest})
cfg=(build/'.config').read_text()
assert 'CONFIG_EXAMPLES_K7RADIO_EMBEDDED_FW=y' in cfg
assert 'CONFIG_INIT_ENTRYPOINT="k7boot_main"' in cfg
sources=json.loads((ev/'source-hashes.json').read_text())
verification={'sha256':hashlib.sha256(raw).hexdigest(),'size':len(raw),
 'compiled':True,'embedded_radio_verified':True,'arrays':arrays,
 'source_hashes':sources,'build_exit_code':0,'ram_loaded':False,
 'storage_written':False,'cold_boot_tested':False}
print(json.dumps({'image':base64.b64encode(raw).decode(),
 'build_log':base64.b64encode((ev/'build.log').read_bytes()).decode(),
 'sync':sync,'verification':verification}))
"""
    bindings = 'BUILD={!r}\nEV={!r}\nINPUTS={!r}\n'.format(BUILD, EV, INPUTS)
    data = json.loads(remote(bindings + code))
    raw = base64.b64decode(data['image'])
    build_log = base64.b64decode(data['build_log'])
    verification = data['verification']
    if hashlib.sha256(raw).hexdigest() != verification['sha256']:
        raise RuntimeError('Collected firmware hash mismatch')
    for rel, digest in verification['source_hashes'].items():
        if hashlib.sha256((ROOT / rel).read_bytes()).hexdigest() != digest:
            raise RuntimeError('Local source changed during build: ' + rel)
    for name, content in (
