  s->target_x=s->sent_x=x; s->target_y=s->sent_y=y;
  return 0;
}
void k7_track_step(struct k7_track_s *s, const struct k7_faces_s *faces,
                    uint64_t now, uint64_t sample, bool halted,
                    struct k7_track_result_s *out)
{
