  puts("K7CLOUD DNS=linked HTTPS=linked");
  puts("K7CLOUD link_selftest=passed");
  puts("K7CLOUD entropy=unverified wall_time=unverified ca=unset");
  puts("K7CLOUD network_request=disabled");
