     (r->raw[K7DR_RESET_PHY0]&0x0c) ||
     (r->raw[K7DR_RESET_PHY1]&0x18)) r->missing|=K7DR_M_RESETS;
  if(r->raw[K7DR_PHY_REF]&BIT(4)) r->missing|=K7DR_M_PHYREF;
  src=(r->raw[K7DR_SEL_VP1]>>8)&7;
  div=(r->raw[K7DR_SEL_VP1]&255)+1;
