#include <errno.h>
#include <string.h>

#define BIT(n) (UINT32_C(1) << (n))
#define CFG_DONE 0x000u
#define VP1_CTRL 0xd00u
#define VP1_INT_CLR 0x0b4u
#define VP1_INT_RAW 0x0bcu
